/* =========================================================
   KRIM GLOBAL FRONTEND FOUNDATION
      Phase 1B — Shared utilities
         ========================================================= */

         (function () {
           "use strict";

             const KRIM = window.KRIM || {};

               /* -----------------------------------------
                    Safe DOM helpers
                      ----------------------------------------- */

                        KRIM.$ = function (selector, root = document) {
                            return root.querySelector(selector);
                              };

                                KRIM.$$ = function (selector, root = document) {
                                    return Array.from(root.querySelectorAll(selector));
                                      };

                                        /* -----------------------------------------
                                             Local storage helpers
                                               ----------------------------------------- */

                                                 KRIM.storage = {
                                                     get(key, fallback = null) {
                                                           try {
                                                                   const value = localStorage.getItem(key);
                                                                           return value === null ? fallback : value;
                                                                                 } catch {
                                                                                         return fallback;
                                                                                               }
                                                                                                   },

                                                                                                       set(key, value) {
                                                                                                             try {
                                                                                                                     localStorage.setItem(key, value);
                                                                                                                             return true;
                                                                                                                                   } catch {
                                                                                                                                           return false;
                                                                                                                                                 }
                                                                                                                                                     },

                                                                                                                                                         remove(key) {
                                                                                                                                                               try {
                                                                                                                                                                       localStorage.removeItem(key);
                                                                                                                                                                               return true;
                                                                                                                                                                                     } catch {
                                                                                                                                                                                             return false;
                                                                                                                                                                                                   }
                                                                                                                                                                                                       }
                                                                                                                                                                                                         };

                                                                                                                                                                                                           /* -----------------------------------------
                                                                                                                                                                                                                Localization foundation
                                                                                                                                                                                                                  ----------------------------------------- */

                                                                                                                                                                                                                    const supportedLocales = [
                                                                                                                                                                                                                        "en", "hi", "ar", "es", "fr",
                                                                                                                                                                                                                            "pt", "de", "it", "nl", "tr",
                                                                                                                                                                                                                                "zh", "ja", "ko", "ru", "bn"
                                                                                                                                                                                                                                  ];

                                                                                                                                                                                                                                    KRIM.locale = {
                                                                                                                                                                                                                                        supported: supportedLocales,

                                                                                                                                                                                                                                            get() {
                                                                                                                                                                                                                                                  const saved = KRIM.storage.get("krim_locale");

                                                                                                                                                                                                                                                        if (saved && supportedLocales.includes(saved)) {
                                                                                                                                                                                                                                                                return saved;
                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                            const browser = (
                                                                                                                                                                                                                                                                                    navigator.language || "en"
                                                                                                                                                                                                                                                                                          ).toLowerCase();

                                                                                                                                                                                                                                                                                                const match = supportedLocales.find(
                                                                                                                                                                                                                                                                                                        locale => browser.startsWith(locale)
                                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                                    return match || "en";
                                                                                                                                                                                                                                                                                                                        },

                                                                                                                                                                                                                                                                                                                            set(locale) {
                                                                                                                                                                                                                                                                                                                                  if (!supportedLocales.includes(locale)) {
                                                                                                                                                                                                                                                                                                                                          locale = "en";
                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                      KRIM.storage.set("krim_locale", locale);

                                                                                                                                                                                                                                                                                                                                                            document.documentElement.lang = locale;
                                                                                                                                                                                                                                                                                                                                                                  document.documentElement.dir =
                                                                                                                                                                                                                                                                                                                                                                          locale === "ar" ? "rtl" : "ltr";

                                                                                                                                                                                                                                                                                                                                                                                window.dispatchEvent(
                                                                                                                                                                                                                                                                                                                                                                                        new CustomEvent("krim:localechange", {
                                                                                                                                                                                                                                                                                                                                                                                                  detail: { locale }
                                                                                                                                                                                                                                                                                                                                                                                                          })
                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                      return locale;
                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                                                                                                              /* -----------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                   Loading state
                                                                                                                                                                                                                                                                                                                                                                                                                                     ----------------------------------------- */

                                                                                                                                                                                                                                                                                                                                                                                                                                       KRIM.loading = {
                                                                                                                                                                                                                                                                                                                                                                                                                                           show(element) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                 if (!element) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                       element.setAttribute(
                                                                                                                                                                                                                                                                                                                                                                                                                                                               "aria-busy",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                       "true"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                             );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   element.dataset.krimLoading = "true";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       },

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           hide(element) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 if (!element) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       element.removeAttribute(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               "aria-busy"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           delete element.dataset.krimLoading;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   /* -----------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Safe error handling
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ----------------------------------------- */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            KRIM.error = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                log(error, context = "KRIM") {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      console.error(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              `[${context}]`,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      error
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                },

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    message(error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  error &&
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          typeof error.message === "string"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return error.message;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return "Something went wrong. Please try again.";
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            /* -----------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 Device / responsive helpers
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   ----------------------------------------- */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     KRIM.device = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         isMobile() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               return window.matchMedia(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       "(max-width: 800px)"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             ).matches;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 },

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     reducedMotion() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           return window.matchMedia(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   "(prefers-reduced-motion: reduce)"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         ).matches;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 /* -----------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Public event system
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ----------------------------------------- */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          KRIM.events = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              emit(name, detail = {}) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    window.dispatchEvent(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            new CustomEvent(name, { detail })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      },

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          on(name, handler) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                window.addEventListener(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                handler
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    window.removeEventListener(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        handler
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              /* -----------------------------------------
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   Initialize
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     ----------------------------------------- */

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       KRIM.locale.set(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           KRIM.locale.get()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               window.KRIM = KRIM;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 document.documentElement.dataset.krimReady = "true";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   KRIM.events.emit(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       "krim:foundation-ready"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         })();